class Solution {
    private int gcd(int a,int b){
        while(b!=0){
            int next=a%b;
            a=b;
            b=next;
        }
        return a;
    }
    public long makeSubKSumEqual(int[] arr,int k){
        int groups=gcd(arr.length,k);
        long answer=0;
        for(int start=0;start<groups;start++){
            List<Integer> values=new ArrayList<>();
            for(int index=start;index<arr.length;index+=groups)values.add(arr[index]);
            Collections.sort(values);
            int median=values.get(values.size()/2);
            for(int value:values)answer+=Math.abs((long)value-median);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    private fun gcd(aInput:Int,bInput:Int):Int{
        var a=aInput;
        var b=bInput;
        while(b!=0){
            val next=a%b;
            a=b;
            b=next
        };
        return a
    }
    fun makeSubKSumEqual(arr:IntArray,k:Int):Long{
        val groups=gcd(arr.size,k);
        var answer=0L;
        for(start in 0 until groups){
            val values=mutableListOf<Int>();
            var index=start;
            while(index<arr.size){
                values.add(arr[index]);
                index+=groups
            };
            values.sort();
            val median=values[values.size/2];
            for(value in values)answer+=kotlin.math.abs(value.toLong()-median)
        };
        return answer
    }
}

